import{_ as a,o,c as r,a2 as s}from"./chunks/framework.D21_4UK8.js";const h=JSON.parse('{"title":"📚 Cuadernos de Estudio (The Lab Journal)","description":"","frontmatter":{},"headers":[],"relativePath":"es/cuadernos.md","filePath":"es/cuadernos.md"}'),i={name:"es/cuadernos.md"};function t(n,e,d,c,l,m){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="📚-cuadernos-de-estudio-the-lab-journal" tabindex="-1">📚 Cuadernos de Estudio (The Lab Journal) <a class="header-anchor" href="#📚-cuadernos-de-estudio-the-lab-journal" aria-label="Permalink to &quot;📚 Cuadernos de Estudio (The Lab Journal)&quot;">​</a></h1><h3 id="articulos-de-ingenieria-de-audio-acustica-y-la-historia-detras-del-tono-clasico" tabindex="-1">Artículos de Ingeniería de Audio, Acústica y la Historia Detrás del Tono Clásico <a class="header-anchor" href="#articulos-de-ingenieria-de-audio-acustica-y-la-historia-detras-del-tono-clasico" aria-label="Permalink to &quot;Artículos de Ingeniería de Audio, Acústica y la Historia Detrás del Tono Clásico&quot;">​</a></h3><p><strong>Main St Audio Labs</strong></p><hr><p>Bienvenido a los <strong>Cuadernos de Estudio</strong> de Main St Audio Labs. Aquí compartimos investigaciones profundas sobre técnicas de microfoneo, acústica de gabinetes, física de la fase, diseño de amplificadores e historias de grabaciones legendarias que inspiran nuestras herramientas de software.</p><hr><h2 id="🎛️-ingenieria-de-audio-tecnicas-de-mezcla" tabindex="-1">🎛️ Ingeniería de Audio &amp; Técnicas de Mezcla <a class="header-anchor" href="#🎛️-ingenieria-de-audio-tecnicas-de-mezcla" aria-label="Permalink to &quot;🎛️ Ingeniería de Audio &amp; Técnicas de Mezcla&quot;">​</a></h2><div class="rock-grid" style="margin-top:1.5rem;margin-bottom:2.5rem;"><div class="rock-card"><div class="rock-card-content"><div style="font-size:0.75rem;text-transform:uppercase;color:var(--vp-c-brand-1);font-weight:bold;margin-bottom:0.35rem;">Ingeniería de Audio &amp; Mezcla</div><h3 class="rock-card-title" style="font-size:1.15rem;margin-bottom:0.5rem;">Guía Maestra: Micrófonos, Tomas y Fase (1x12 Hardwood)</h3><p class="rock-card-desc" style="font-size:0.88rem;line-height:1.5;"> La física acústica del altavoz EVM-12L, la alineación por transiente a muestra cero ($t=0$), las diferencias entre tomas Left/Right y el secreto para conseguir una pared de guitarras en estéreo gigante en <strong>una sola pista del DAW</strong> sin duplicar eventos. </p><div class="rock-card-footer" style="margin-top:1rem;"><a href="/es/guia-microfonos-tomas" class="rock-btn rock-btn-primary" style="padding:0.4rem 0.9rem;font-size:0.82rem;">Leer Artículo Completo ➔</a></div></div></div></div><hr><h2 id="📖-historia-del-tono-leyendas-de-grabacion" tabindex="-1">📖 Historia del Tono &amp; Leyendas de Grabación <a class="header-anchor" href="#📖-historia-del-tono-leyendas-de-grabacion" aria-label="Permalink to &quot;📖 Historia del Tono &amp; Leyendas de Grabación&quot;">​</a></h2><div class="rock-grid" style="margin-top:1.5rem;margin-bottom:2rem;"><div class="rock-card"><div class="rock-card-content"><div style="font-size:0.75rem;text-transform:uppercase;color:var(--vp-c-brand-1);font-weight:bold;margin-bottom:0.35rem;">Historia del Equipamiento</div><h3 class="rock-card-title" style="font-size:1.15rem;margin-bottom:0.5rem;">El Rey Indestructible: Electro-Voice EVM-12L</h3><p class="rock-card-desc" style="font-size:0.88rem;line-height:1.5;"> La historia del altavoz de 300 Watts que desafió a los conos británicos convencionales. Por qué Keith Richards, Stevie Ray Vaughan, Zakk Wylde y Joe Bonamassa lo convirtieron en su arma secreta de tono y headroom. </p><div class="rock-card-footer" style="margin-top:1rem;"><a href="/es/electro-voice-evm12l" class="rock-btn rock-btn-primary" style="padding:0.4rem 0.9rem;font-size:0.82rem;">Leer Historia ➔</a></div></div></div><div class="rock-card"><div class="rock-card-content"><div style="font-size:0.75rem;text-transform:uppercase;color:var(--vp-c-brand-1);font-weight:bold;margin-bottom:0.35rem;">Crónicas de Estudio</div><h3 class="rock-card-title" style="font-size:1.15rem;margin-bottom:0.5rem;">Los Stones no pagan por amplis: Mesa/Boogie 1978–1981</h3><p class="rock-card-desc" style="font-size:0.88rem;line-height:1.5;"> Cómo Keith Richards y los Rolling Stones adoptaron los amplificadores Mark I y Mark II durante las sesiones de París y las giras norteamericanas, definiendo la era dorada de <em>Some Girls</em>, <em>Emotional Rescue</em> y <em>Tattoo You</em>. </p><div class="rock-card-footer" style="margin-top:1rem;"><a href="/es/history-mesa-stones" class="rock-btn rock-btn-primary" style="padding:0.4rem 0.9rem;font-size:0.82rem;">Leer Crónica ➔</a></div></div></div></div>',11)])])}const p=a(i,[["render",t]]);export{h as __pageData,p as default};
